custom_css:
.sc-tw :root{
            color-scheme: light;
            --white: oklch(98% 0.01 240);
            --white-2: oklch(96.8% 0.01 240);
            --graphite: oklch(18% 0.05 30);
            --graphite-2: oklch(14% 0.04 30);
            --slate: oklch(52% 0.09 255);
            --slate-2: oklch(64% 0.11 255);
            --blue: oklch(71% 0.15 255);
            --ink: oklch(18% 0.02 240);
        }.sc-tw *{
            box-sizing: border-box;
        }.sc-tw html{
            scroll-behavior: smooth;
        }.sc-tw{
            margin: 0;
            overflow-x: hidden;
            font-family: "Inter Tight", sans-serif;
            background:
                radial-gradient(circle at 14% 10%, rgba(80, 128, 196, .08), transparent 16%),
                radial-gradient(circle at 84% 14%, rgba(0, 0, 0, .035), transparent 15%),
                linear-gradient(180deg, var(--white) 0%, var(--white-2) 100%);
            color: var(--ink);
        }.sc-tw body::before{
            content: "";
            position: fixed;
            inset: 0;
            pointer-events: none;
            background-image:
                linear-gradient(rgba(0, 0, 0, .03) 1px, transparent 1px),
                linear-gradient(90deg, rgba(0, 0, 0, .03) 1px, transparent 1px);
            background-size: 120px 120px;
            opacity: .26;
            z-index: -2;
        }.sc-tw .mono{
            font-family: "IBM Plex Mono", monospace;
        }.sc-tw .display{
            font-weight: 900;
        }.sc-tw .audit-bar{
            position: fixed;
            inset: 0 0 auto 0;
            z-index: 80;
            background: rgba(255, 255, 255, .82);
            backdrop-filter: blur(14px) brightness(1.02);
            border-bottom: 1px solid rgba(0, 0, 0, .08);
        }.sc-tw .audit-inner{
            width: min(1600px, calc(100% - 28px));
            margin: 0 auto;
            min-height: 64px;
            display: grid;
            grid-template-columns: auto 1fr auto;
            gap: 16px;
            align-items: center;
        }.sc-tw .brand{
            display: flex;
            align-items: center;
            gap: 14px;
            min-width: 0;
        }.sc-tw .brand-mark{
            width: 40px;
            height: 40px;
            display: grid;
            place-items: center;
            border: 1px solid rgba(0, 0, 0, .12);
            background: linear-gradient(180deg, rgba(255, 255, 255, .98), rgba(247, 247, 247, .9));
            border-radius: 3px;
        }.sc-tw .brand-copy{
            min-width: 0;
        }.sc-tw .brand-copy .name{
            font-size: 11px;
            text-transform: uppercase;
            color: rgba(0, 0, 0, .55);
        }.sc-tw .brand-copy .sub{
            margin-top: 4px;
            font-size: 14px;
            color: rgba(0, 0, 0, .86);
            white-space: nowrap;
        }.sc-tw .audit-nav{
            display: flex;
            justify-content: center;
            gap: 20px;
            overflow-x: auto;
            scrollbar-width: none;
            text-transform: uppercase;
            font-size: 10px;
            color: rgba(0, 0, 0, .55);
        }.sc-tw .audit-nav::-webkit-scrollbar{
            display: none;
        }.sc-tw .audit-nav a{
            text-decoration: none;
            color: inherit;
            white-space: nowrap;
            transition: .25s ease;
        }.sc-tw .audit-nav a:hover{
            color: var(--slate);
        }.sc-tw .audit-actions{
            display: flex;
            align-items: center;
            gap: 12px;
        }.sc-tw .meter{
            width: 220px;
            height: 8px;
            background: rgba(0, 0, 0, .08);
            overflow: hidden;
            border-radius: 2px;
        }.sc-tw .meter span{
            display: block;
            height: 100%;
            width: 78%;
            background: linear-gradient(90deg, rgba(65, 120, 196, .88), rgba(116, 165, 255, .98));
        }.sc-tw .aero{
            position: relative;
            overflow: hidden;
            height: 40px;
            padding: 0 16px;
            border-radius: 3px;
            border: 1px solid rgba(0, 0, 0, .12);
            background: linear-gradient(180deg, rgba(255, 255, 255, .98), rgba(246, 246, 246, .86));
            color: rgba(0, 0, 0, .84);
            text-transform: uppercase;
            font-size: 10px;
            cursor: pointer;
            transition: transform .45s cubic-bezier(.16, 1, .3, 1), border-color .35s ease, box-shadow .35s ease;
            box-shadow: inset 0 1px 0 rgba(255, 255, 255, .9);
        }.sc-tw .aero::after{
            content: "";
            position: absolute;
            inset: 0;
            opacity: 0;
            background:
                linear-gradient(90deg, transparent, rgba(74, 145, 255, .26), transparent);
            transition: .35s ease;
            pointer-events: none;
        }.sc-tw .aero:hover{
            transform: translateY(-2px);
            border-color: rgba(74, 145, 255, .4);
            box-shadow:
                inset 0 1px 0 rgba(255, 255, 255, .96),
                0 0 0 1px rgba(74, 145, 255, .14);
        }.sc-tw .aero:hover::after{
            opacity: 1;
        }.sc-tw .hero{
            position: relative;
            min-height: 100svh;
            display: grid;
            grid-template-columns: 1fr;
            background: var(--white);
            padding-top: 64px;
            overflow: hidden;
        }.sc-tw .hero-grid{
            position: relative;
            z-index: 10;
            width: min(1600px, calc(100% - 28px));
            margin: 0 auto;
            min-height: calc(100svh - 64px);
            display: grid;
            grid-template-columns: 1fr 1fr;
            align-items: stretch;
        }.sc-tw .hero-copy{
            position: relative;
            z-index: 4;
            padding: 72px 24px 48px 0;
            display: flex;
            align-items: center;
            justify-content: flex-start;
            background: transparent;
            border-right: none;
        }.sc-tw .hero-side{
            position: relative;
            background: transparent;
            overflow: visible;
            min-height: calc(100svh - 64px);
        }.sc-tw .video-shell{
            position: absolute;
            inset: 0;
            z-index: 1;
            overflow: hidden;
            -webkit-mask-image: linear-gradient(to right, transparent 0%, transparent 20%, black 55%, black 100%);
            mask-image: linear-gradient(to right, transparent 0%, transparent 20%, black 55%, black 100%);
            filter: saturate(1.06) contrast(1.04) brightness(.96);
        }.sc-tw .hero-copy-inner{
            width: 100%;
            max-width: 640px;
            padding: 18px 18px 18px 0;
        }.sc-tw .eyebrow{
            display: inline-flex;
            align-items: center;
            gap: 10px;
            padding: 10px 14px;
            border-radius: 3px;
            border: 1px solid rgba(0, 0, 0, .08);
            background: rgba(255, 255, 255, .72);
            text-transform: uppercase;
            font-size: 10px;
            color: rgba(0, 0, 0, .62);
            backdrop-filter: blur(8px);
        }.sc-tw .eyebrow span{
            width: 8px;
            height: 8px;
            background: var(--blue);
            display: inline-block;
        }.sc-tw .hero-title{
            margin-top: 22px;
            font-size: clamp(4.6rem, 8.8vw, 8.8rem);
            line-height: .86;
            color: #080808;
            text-transform: none;
        }.sc-tw .hero-title .line{
            overflow: hidden;
            position: relative;
        }.sc-tw .hero-title .line span{
            display: inline-block;
            transform: translateY(100%);
            opacity: 0;
            filter: blur(8px);
        }.sc-tw .typed{
            animation: typedIn .8s cubic-bezier(.16, 1, .3, 1) forwards;
        }.sc-tw .glitch{
            position: relative;
            display: inline-block;
        }.sc-tw .glitch::before,.sc-tw .glitch::after{
            content: attr(data-text);
            position: absolute;
            left: 0;
            top: 0;
            width: 100%;
            overflow: hidden;
            opacity: .6;
            pointer-events: none;
            clip-path: inset(0 0 0 0);
        }.sc-tw .glitch::before{
            transform: translate(1px, 0);
            color: #4a87ff;
            animation: glitchA 1.8s infinite linear alternate-reverse;
        }.sc-tw .glitch::after{
            transform: translate(-1px, 0);
            color: #9ec0ff;
            animation: glitchB 2.2s infinite linear alternate-reverse;
        }.sc-tw .hero-copy-text{
            margin-top: 24px;
            max-width: 560px;
            font-size: 16px;
            line-height: 2;
            color: rgba(0, 0, 0, .72);
        }.sc-tw .hero-specs{
            margin-top: 20px;
            display: flex;
            flex-wrap: wrap;
            gap: 10px;
        }.sc-tw .hero-specs span{
            padding: 10px 12px;
            border: 1px solid rgba(0, 0, 0, .08);
            background: rgba(255, 255, 255, .84);
            border-radius: 3px;
            text-transform: uppercase;
            font-size: 10px;
            color: rgba(0, 0, 0, .62);
        }.sc-tw .hero-actions{
            margin-top: 26px;
            display: flex;
            gap: 12px;
            flex-wrap: wrap;
        }.sc-tw .hero-actions button{
            height: 46px;
            padding: 0 18px;
            border-radius: 3px;
            border: none;
            cursor: pointer;
            font-size: 10px;
            text-transform: uppercase;
        }.sc-tw .video-shell{
            position: absolute;
            inset: 0 -12% 0 -8%;
            z-index: 2;
            overflow: hidden;
            -webkit-mask: url(#dataPulseMask);
            mask: url(#dataPulseMask);
            filter: saturate(1.06) contrast(1.04) brightness(.96);
        }.sc-tw .video-shell video{
            width: 100%;
            height: 100%;
            object-fit: cover;
            transform: scale(1.06);
            will-change: transform;
        }.sc-tw .video-shell::before{
            content: "";
            position: absolute;
            inset: 0;
            background:
                radial-gradient(circle at 18% 20%, rgba(255, 255, 255, .18), transparent 16%),
                radial-gradient(circle at 65% 28%, rgba(77, 143, 255, .2), transparent 14%),
                linear-gradient(180deg, rgba(255, 255, 255, .08), rgba(0, 0, 0, .18));
            z-index: 2;
            pointer-events: none;
        }.sc-tw .video-shell::after{
            content: "";
            position: absolute;
            inset: -2%;
            background: linear-gradient(90deg, rgba(255, 255, 255, .22), transparent 24%);
            pointer-events: none;
            mix-blend-mode: screen;
        }.sc-tw .ticker-stack{
            position: absolute;
            inset: 20px 18px 20px auto;
            z-index: 6;
            width: min(360px, 46%);
            display: flex;
            flex-direction: column;
            gap: 10px;
        }.sc-tw .ticker{
            padding: 14px 16px;
            background: rgba(255, 255, 255, .1);
            border: 1px solid rgba(255, 255, 255, .12);
            backdrop-filter: blur(40px) brightness(1.1);
            -webkit-backdrop-filter: blur(40px) brightness(1.1);
            color: white;
            border-radius: 3px;
            box-shadow: inset 0 1px 0 rgba(255, 255, 255, .1);
        }.sc-tw .ticker .top{
            display: flex;
            justify-content: space-between;
            gap: 16px;
            align-items: center;
            text-transform: uppercase;
            font-size: 10px;
            color: black;
        }.sc-tw .ticker .value{
            margin-top: 10px;
            font-size: 28px;
            line-height: 1;
            color: #050505;
        }.sc-tw .ticker .small{
            margin-top: 8px;
            font-family: "IBM Plex Mono", monospace;
            font-size: 13px;
            line-height: 1.7;
            color: black;
        }.sc-tw .section{
            padding: 110px 0;
        }.sc-tw .shell{
            width: min(1600px, calc(100% - 28px));
            margin: 0 auto;
        }.sc-tw .section-h{
            display: flex;
            justify-content: space-between;
            gap: 22px;
            align-items: flex-end;
            margin-bottom: 26px;
        }.sc-tw .section-h h2{
            font-size: clamp(2.6rem, 5.2vw, 5.8rem);
            line-height: .88;
            color: #090909;
        }.sc-tw .section-h p{
            max-width: 430px;
            color: rgba(0, 0, 0, .66);
            line-height: 1.95;
        }.sc-tw .dual-stream{
            position: relative;
            display: grid;
            grid-template-columns: .45fr .55fr;
            gap: 18px;
            align-items: stretch;
        }.sc-tw .ledger-panel{
            padding: 38px;
            background:
                linear-gradient(180deg, rgba(255, 255, 255, .95), rgba(248, 248, 248, .84));
            border: 1px solid rgba(0, 0, 0, .08);
            border-radius: 3px;
        }.sc-tw .ledger-panel .label{
            text-transform: uppercase;
            font-size: 10px;
            color: rgba(0, 0, 0, .54);
        }.sc-tw .ledger-panel h3{
            margin-top: 16px;
            font-size: clamp(2rem, 4vw, 4.3rem);
            line-height: .9;
            color: #050505;
        }.sc-tw .ledger-panel p{
            margin-top: 18px;
            line-height: 2;
            color: rgba(0, 0, 0, .68);
            max-width: 52ch;
        }.sc-tw .audit-list{
            margin-top: 22px;
            border-top: 1px solid rgba(0, 0, 0, .08);
        }.sc-tw .audit-row{
            display: grid;
            grid-template-columns: auto 1fr auto;
            gap: 14px;
            align-items: center;
            padding: 14px 0;
            border-bottom: 1px solid rgba(0, 0, 0, .08);
            font-family: "IBM Plex Mono", monospace;
            font-size: 11px;
            text-transform: uppercase;
            color: rgba(0, 0, 0, .7);
        }.sc-tw .audit-row strong{
            color: #000;
            font-family: inherit;
        }.sc-tw .monitor{
            position: relative;
            overflow: hidden;
            border-radius: 3px;
            border: 1px solid rgba(0, 0, 0, .08);
            background:
                linear-gradient(180deg, rgba(255, 255, 255, .9), rgba(245, 247, 250, .82));
            min-height: 580px;
            display: grid;
            grid-template-columns: 1fr 1fr;
        }.sc-tw .monitor::before{
            content: "";
            position: absolute;
            inset: 0;
            background:
                linear-gradient(180deg, rgba(255, 255, 255, .42), transparent 20%),
                linear-gradient(90deg, rgba(74, 143, 255, .08), transparent 52%);
            pointer-events: none;
        }.sc-tw .monitor .pane{
            padding: 22px;
            border-right: 1px solid rgba(0, 0, 0, .08);
        }.sc-tw .monitor .pane:last-child{
            border-right: none;
        }.sc-tw .pane-head{
            display: flex;
            justify-content: space-between;
            align-items: center;
            gap: 14px;
            text-transform: uppercase;
            font-size: 10px;
            color: rgba(0, 0, 0, .55);
        }.sc-tw .box{
            margin-top: 16px;
            padding: 18px;
            border: 1px solid rgba(0, 0, 0, .08);
            background: rgba(255, 255, 255, .9);
            border-radius: 3px;
        }.sc-tw .box .name{
            text-transform: uppercase;
            font-size: 10px;
            color: rgba(0, 0, 0, .5);
        }.sc-tw .box .amount{
            margin-top: 10px;
            font-size: 34px;
            color: #050505;
        }.sc-tw .box .desc{
            margin-top: 10px;
            color: rgba(0, 0, 0, .66);
            line-height: 1.85;
            font-size: 14px;
        }.sc-tw .mini-graph{
            margin-top: 18px;
            width: 100%;
            height: 160px;
            border: 1px solid rgba(0, 0, 0, .08);
            background:
                linear-gradient(180deg, rgba(255, 255, 255, .96), rgba(246, 248, 251, .86));
            border-radius: 3px;
            padding: 16px;
        }.sc-tw .metrics{
            margin-top: 18px;
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 12px;
        }.sc-tw .metric{
            padding: 16px;
            border: 1px solid rgba(0, 0, 0, .08);
            background: rgba(255, 255, 255, .92);
            border-radius: 3px;
        }.sc-tw .metric .k{
            text-transform: uppercase;
            font-size: 10px;
            color: rgba(0, 0, 0, .55);
        }.sc-tw .metric .v{
            margin-top: 10px;
            font-size: 28px;
            color: #050505;
        }.sc-tw .telemetry{
            padding: 110px 0;
            background:
                linear-gradient(180deg, #0f1114 0%, #11151a 100%);
            color: white;
        }.sc-tw .telemetry-shell{
            width: min(1600px, calc(100% - 28px));
            margin: 0 auto;
        }.sc-tw .telemetry-head{
            display: flex;
            justify-content: space-between;
            gap: 20px;
            align-items: flex-end;
            margin-bottom: 28px;
        }.sc-tw .telemetry-head h2{
            font-size: clamp(2.7rem, 5.4vw, 5.6rem);
            line-height: .88;
        }.sc-tw .telemetry-head p{
            max-width: 440px;
            color: rgba(255, 255, 255, .66);
            line-height: 1.95;
        }.sc-tw .grid-board{
            display: grid;
            grid-template-columns: repeat(12, 1fr);
            gap: 16px;
        }.sc-tw .tile{
            grid-column: span 4;
            min-height: 220px;
            padding: 20px;
            border: 1px solid rgba(255, 255, 255, .08);
            background:
                linear-gradient(180deg, rgba(255, 255, 255, .05), rgba(255, 255, 255, .02));
            border-radius: 3px;
            position: relative;
            overflow: hidden;
            opacity: 0;
            transform: translateY(24px);
            transition: opacity .6s ease, transform .6s cubic-bezier(.16, 1, .3, 1);
        }.sc-tw .tile.in{
            opacity: 1;
            transform: translateY(0);
        }.sc-tw .tile::before{
            content: "";
            position: absolute;
            inset: 0;
            background:
                linear-gradient(90deg, rgba(73, 136, 255, .18), transparent 60%),
                linear-gradient(180deg, rgba(255, 255, 255, .04), transparent 25%);
            pointer-events: none;
        }.sc-tw .tile .t{
            display: flex;
            justify-content: space-between;
            align-items: center;
            text-transform: uppercase;
            font-size: 10px;
            color: rgba(255, 255, 255, .55);
        }.sc-tw .tile h3{
            margin-top: 18px;
            font-size: clamp(1.6rem, 2.8vw, 2.8rem);
            line-height: .95;
            color: white;
        }.sc-tw .tile p{
            margin-top: 14px;
            color: rgba(255, 255, 255, .68);
            line-height: 1.85;
            max-width: 42ch;
            font-size: 14px;
        }.sc-tw .tile svg{
            width: 100%;
            height: 84px;
            margin-top: 16px;
            overflow: visible;
        }.sc-tw .tile.wide{
            grid-column: span 8;
        }.sc-tw .tile.tall{
            min-height: 278px;
        }.sc-tw .telemetry-foot{
            margin-top: 16px;
            display: grid;
            grid-template-columns: repeat(3, 1fr);
            gap: 16px;
        }.sc-tw .signal{
            padding: 18px 20px;
            border: 1px solid rgba(255, 255, 255, .08);
            background: rgba(255, 255, 255, .03);
            border-radius: 3px;
        }.sc-tw .signal .name{
            text-transform: uppercase;
            font-size: 10px;
            color: rgba(255, 255, 255, .52);
        }.sc-tw .signal .value{
            margin-top: 10px;
            font-size: 30px;
        }.sc-tw .ledger-footer{
            padding: 110px 0 90px;
            background:
                linear-gradient(180deg, #111 0%, #0b0c0f 100%);
            color: white;
        }.sc-tw .ledger-shell{
            width: min(1600px, calc(100% - 28px));
            margin: 0 auto;
            display: grid;
            grid-template-columns: 1fr .9fr;
            gap: 18px;
        }.sc-tw .ledger-card{
            padding: 36px;
            border: 1px solid rgba(255, 255, 255, .08);
            background: rgba(255, 255, 255, .03);
            border-radius: 3px;
        }.sc-tw .ledger-card h2{
            font-size: clamp(2.7rem, 5vw, 5.2rem);
            line-height: .9;
        }.sc-tw .ledger-card p{
            margin-top: 16px;
            color: rgba(255, 255, 255, .68);
            line-height: 2;
            max-width: 760px;
        }.sc-tw pre{
            margin: 0;
            white-space: pre-wrap;
            word-break: break-word;
            font-family: "IBM Plex Mono", monospace;
            font-size: 12px;
            line-height: 1.95;
            color: rgba(255, 255, 255, .78);
        }.sc-tw .capabilities{
            display: grid;
            gap: 14px;
        }.sc-tw .cap{
            padding: 18px 20px;
            border: 1px solid rgba(255, 255, 255, .08);
            background: rgba(255, 255, 255, .03);
            border-radius: 3px;
            font-family: "IBM Plex Mono", monospace;
            font-size: 12px;
            line-height: 1.8;
            color: rgba(255, 255, 255, .76);
        }.sc-tw .bottom-line{
            margin-top: 24px;
            height: 1px;
            background: linear-gradient(90deg, transparent, rgba(255, 255, 255, .25), transparent);
        }.sc-tw .footer-bar{
            margin-top: 18px;
            display: flex;
            justify-content: space-between;
            gap: 20px;
            flex-wrap: wrap;
            color: rgba(255, 255, 255, .55);
            font-size: 12px;
            text-transform: uppercase;
        }

        @keyframes typedIn {from{
                opacity: 0;
                filter: blur(10px);
                transform: translateY(12px);
            }to{
                opacity: 1;
                filter: blur(0);
                transform: translateY(0);
            }
        }

        @keyframes glitchA {0%{
                clip-path: inset(0 0 92% 0);
            }20%{
                clip-path: inset(12% 0 78% 0);
            }40%{
                clip-path: inset(54% 0 30% 0);
            }60%{
                clip-path: inset(28% 0 56% 0);
            }80%{
                clip-path: inset(64% 0 14% 0);
            }100%{
                clip-path: inset(0 0 0 0);
            }
        }

        @keyframes glitchB {0%{
                clip-path: inset(84% 0 0 0);
            }20%{
                clip-path: inset(72% 0 8% 0);
            }40%{
                clip-path: inset(18% 0 58% 0);
            }60%{
                clip-path: inset(42% 0 32% 0);
            }80%{
                clip-path: inset(6% 0 80% 0);
            }100%{
                clip-path: inset(0 0 0 0);
            }
        }

        @keyframes sheen {to{
                transform: translateX(240%) rotate(10deg);
            }
        }.sc-tw ::view-transition-old(root),.sc-tw ::view-transition-new(root){
            animation-duration: .72s;
            animation-timing-function: cubic-bezier(.16, 1, .3, 1);
        }

        @media (max-width: 1180px) {.sc-tw .audit-inner{
                grid-template-columns: 1fr auto;
            }.sc-tw .audit-nav{
                display: none;
            }.sc-tw .hero-grid{
                grid-template-columns: 1fr;
            }.sc-tw .hero-copy{
                border-right: none;
                border-bottom: 1px solid rgba(0, 0, 0, .08);
            }.sc-tw .hero-side{
                min-height: 72vh;
            }.sc-tw .dual-stream,.sc-tw .ledger-shell{
                grid-template-columns: 1fr;
            }.sc-tw .grid-board{
                grid-template-columns: repeat(6, 1fr);
            }.sc-tw .tile,.sc-tw .tile.wide{
                grid-column: span 6;
            }.sc-tw .telemetry-foot{
                grid-template-columns: 1fr;
            }
        }

        @media (max-width: 760px) {.sc-tw .audit-inner{
                width: min(100% - 18px, 1600px);
